package vn.com.apartment.commercial;import java.util.List;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface CommercialParkingVehicleRepository extends JpaRepository<CommercialParkingVehicle,Long>{boolean existsByPlateNumberIgnoreCaseAndActiveTrue(String plate);@Query("select v from CommercialParkingVehicle v join fetch v.assignment a join fetch a.space where v.active=true order by v.plateNumber")List<CommercialParkingVehicle> findAllActiveDetailed();@Query("select v from CommercialParkingVehicle v where v.assignment.id=:assignmentId and v.active=true")List<CommercialParkingVehicle> findActiveByAssignment(@Param("assignmentId")Long assignmentId);}
